module club_lighting (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] threshold,\n    input wire [2:0] height,\n    input wire [3:0] data_in,\n    input wire [5:0] addr,\n    input wire wr,\n    output reg done,\n    output reg [15:0] cost_out\n);\n\n    // Memory and parameters\n    parameter GRID_R = 8;\n    parameter GRID_C = 8;\n    reg [3:0] strength_ram [0:63];\n    \n    // State declarations\n    localparam [2:0] S_IDLE = 3'd0;\n    localparam [2:0] S_COMPUTE_LIGHT = 3'd1;\n    localparam [2:0] S_COMPUTE_FENCE = 3'd2;\n    localparam [2:0] S_DONE = 3'd3;\n    reg [2:0] state, next_state;\n    \n    // Computation registers\n    reg [5:0] cell_idx;\n    reg [5:0] source_idx;\n    reg [15:0] light_sum;\n    reg [63:0] meets_std;\n    reg [15:0] light_levels [0:63];\n    \n    // Helper functions\n    function [5:0] get_row(input [5:0] idx);\n        get_row = idx / GRID_C;\n    endfunction\n    \n    function [5:0] get_col(input [5:0] idx);\n        get_col = idx % GRID_C;\n    endfunction\n    \n    // Weight calculation\n    reg [15:0] denominator;\n    reg [15:0] weight;\n    wire [15:0] threshold_q88 = {threshold, 8'b0};\n    wire [15:0] height_sq = height * height;\n    \n    // Write memory\n    always @(posedge clk) begin\n        if (wr) begin\n            strength_ram[addr] <= data_in;\n        end\n    end\n    \n    // Main state machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= S_IDLE;\n            done <= 1'b0;\n            cost_out <= 16'd0;\n            cell_idx <= 6'd0;\n            source_idx <= 6'd0;\n            light_sum <= 16'd0;\n            meets_std <= 64'd0;\n            \n            for (integer i = 0; i < 64; i = i + 1) begin\n                light_levels[i] <= 16'd0;\n            end\n        end\n        else begin\n            state <= next_state;\n            \n            case (state)\n                S_IDLE: begin\n                    if (start) begin\n                        cell_idx <= 6'd0;\n                        next_state = S_COMPUTE_LIGHT;\n                    end\n                    done <= 1'b0;\n                end\n                \n                S_COMPUTE_LIGHT: begin\n                    if (cell_idx < 6'd63) begin\n                        if (source_idx == cell_idx) begin\n                            // Add self contribution (strength/H²)\n                            light_sum <= light_sum + ({12'd0, strength_ram[cell_idx]} * 16'd256) / ({13'd0, height});\n                            source_idx <= source_idx + 6'd1;\n                        end\n                        else if (source_idx < 6'd64) begin\n                            // Calculate weight for this source-cell pair\n                            denominator = (\n                                (get_row(source_idx) - get_row(cell_idx)) ** 2 +\n                                (get_col(source_idx) - get_col(cell_idx)) ** 2 +\n                                height_sq\n                            );\n                            \n                            weight <= (denominator > 16'd0) ? (16'd256 / denominator) : 16'd0;\n                            light_sum <= light_sum + ({12'd0, strength_ram[source_idx]} * weight);\n                            source_idx <= source_idx + 6'd1;\n                        end\n                        else begin\n                            // Finalize light level for current cell\n                            light_levels[cell_idx] <= light_sum;\n                            meets_std[cell_idx] <= (light_sum >= threshold_q88);\n                            cell_idx <= cell_idx + 6'd1;\n                            source_idx <= 6'd0;\n                            light_sum <= 16'd0;\n                        end\n                    end\n                    else begin\n                        next_state <= S_COMPUTE_FENCE;\n                        cell_idx <= 6'd0;\n                        cost_out <= 16'd0;\n                    end\n                end\n                \n                S_COMPUTE_FENCE: begin\n                    if (cell_idx < 6'd63) begin\n                        // Check right neighbor (same row)\n                        if ((get_col(cell_idx) < 3'd7) && (meets_std[cell_idx] != meets_std[cell_idx + 1])) begin\n                            cost_out <= cost_out + 16'd1;\n                        end\n                        \n                        // Check bottom neighbor (same column)\n                        if ((get_row(cell_idx) < 3'd7) && (meets_std[cell_idx] != meets_std[cell_idx + GRID_C])) begin\n                            cost_out <= cost_out + 16'd1;\n                        end\n                        \n                        cell_idx <= cell_idx + 6'd1;\n                    end\n                    else begin\n                        next_state <= S_DONE;\n                    end\n                end\n                \n                S_DONE: begin\n                    done <= 1'b1;\n                    next_state <= S_IDLE;\n                end\n                \n                default: next_state <= S_IDLE;\n            endcase\n        end\n    end\nendmodule